/// <summary>
/// Extension class to override the Print Management settings
/// </summary>
[ExtensionOf(classStr(SrsReportRunPrinter))]
internal final class METSrsReportRunPrinter_Extension
{
}

Method.Source:
    /// <summary>
    /// This method is COC'ed to override the print mangement settings (initially for overriding To Email address of Purchase confirmation report)
    /// </summary>
    public void printReport()
    {
        #OCCRetryCount
        SrsReportDataContract metContract = reportContract;
        boolean               metUpdatePOSentFlag;
        RefRecId              metPurchTableRecId;

        //check if print method is Email and contract type is Purchase order confirmation (we can add in condition for a particular report as well )
        if(metContract 
            && SRSPrintMediumType::Email 
            && metContract.parmRdpContract() as PurchPurchaseOrderContract)//MPJ_27166_BuyPOFSDEnhancements
        {
            PurchPurchaseOrderContract metPurchConfirmContract  = metContract.parmRdpContract() as PurchPurchaseOrderContract;
            
            VendPurchOrderJour  metVendPurchOrderJourStd;
            PurchTable          metpurchTableStd;
            METPurchTable       metPurchTable;

            select firstonly PurchId 
                from metVendPurchOrderJourStd
                    where metVendPurchOrderJourStd.RecId == metPurchConfirmContract.parmRecordId()
                join recid 
                from metpurchTableStd
                    where metpurchTableStd.PurchId == metVendPurchOrderJourStd.PurchId
                join POSubMode 
                from metpurchTable
                    where metPurchTable.PurchTable == metpurchTableStd.Recid;

            metPurchTableRecId = metpurchTableStd.RecId;
            
            //update To Email address based on Vendor Site settings of the purchase order
            //Modified by kavya for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> Begin
            if(metPurchTableRecId && METVendSiteSettingsSetup::existsPOVendSiteRecord(metVendPurchOrderJourStd.PurchId))
            {
                if(this.metIsFirstConfirmation(metVendPurchOrderJourStd))// MPJ_27166_BuyPOFSDEnhancements
                {
                    if(metPurchTable.POSubMode)
                    {
                        metUpdatePOSentFlag = true;
                        if(metPurchTable.POIHGEmailEDIAddress && METVendParameters::find().IGHPOHeadEmailEDIAutoDefConfirmOverride)
                        {
                            this.metUpdateToEmailAddress(metPurchTable.POIHGEmailEDIAddress);
                        }
                        else
                        {
                            this.metUpdateToEmailAddress(METVendSiteSettingsSetup::getPurchOrderEmailAddress(metVendPurchOrderJourStd.PurchId));
                        }
                        

                        if(metPurchTable.POSubMode == METConstants::EDI || metPurchTable.POSubMode == METConstants::None) 
                        {
                            this.metSkipSendingEmail();
                        }
                    }
                    else
                    {
                        throw error("@MET:METPOSubModeErrorMsg");
                    }
                }
                // MPJ_27166_BuyPOFSDEnhancements
                else
                {
                    if(metPurchTable.POChngSubMode)
                    {
                        if(metPurchTable.POIHGEmailEDIAddressChnge && METVendParameters::find().IGHPOHeadEmailEDIAutoDefConfirmOverride)
                        {
                            metUpdatePOSentFlag = true;
                            this.metUpdateToEmailAddress(metPurchTable.POIHGEmailEDIAddressChnge);
                        }
                        else
                        {
                            metUpdatePOSentFlag = true;
                            this.metUpdateToEmailAddress(METVendSiteSettingsSetup::getPurchOrderEmailAddress(metVendPurchOrderJourStd.PurchId));
                        }   
                        
                        if(metPurchTable.POChngSubMode == METConstants::EDI || metPurchTable.POChngSubMode == METConstants::None)
                        {
                            metUpdatePOSentFlag = true;
                            this.metSkipSendingEmail();
                        }
                    }
                    else
                    {
                        throw error("@MET:METPOSubModeErrorMsg");
                    }

                }
                // MPJ_27166_BuyPOFSDEnhancements
            }
            //Modified by kavya for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> End
        }

        next printReport();

        if(metUpdatePOSentFlag && metPurchTableRecId)
        {
            try
            {
                ttsbegin;
                METPurchTable metPurchTable = METPurchTable::findByPurchTable(metPurchTableRecId,true);
                metPurchTable.POSentFlag = NoYes::Yes;
                metPurchTable.update();
                ttscommit;
            }
            catch(Exception::UpdateConflict)
            {
                error("@MET:METPOUpdateConflict");
                throw Exception::UpdateConflictNotRecovered;
            }
            catch(Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                retry;
            }
            catch(Exception::Error)
            {
                error("@MET:METPOUpdateConflict");
            }
            
        }
        
    }

/// <summary>
/// Update the email address
/// </summary>
/// <param name = "_metToEmailAddresses">Email address</param>
private void metUpdateToEmailAddress(METEmailAddress _metToEmailAddresses)
{
    if(_metToEmailAddresses)
    {
        SrsReportEMailDataContract  metEmailContract = printSettings.parmEMailContract();
        metEmailContract.parmTo(_metToEmailAddresses);
    }
}

/// <summary>
/// Skip sending an email
/// </summary>
private void metSkipSendingEmail()
{
    printSettings.parmEMailContract(null);
}

    /// <summary>
    /// check whether PO confirmation is the first one. Assume that document number doesn't exceed 99 for one PO
    /// MPJ_27166_BuyPOFSDEnhancements
    /// </summary>
    /// <param name = "_vendPurchOrderJour">VendPurchOrderJour</param>
    /// <returns>Return True if this is the first confirmation</returns>
    private boolean metIsFirstConfirmation(VendPurchOrderJour  _vendPurchOrderJour)
    {
        str     metLastTwoChar = subStr(_vendPurchOrderJour.PurchOrderDocNum,strLen(_vendPurchOrderJour.PurchOrderDocNum),-2);
        str     metDocVersion;
        boolean ret = false;

        switch(metLastTwoChar)
        {
            case '11','21','31','41','51','61','71','81','91':
                ret = false;
                break;
            default:
                metDocVersion  = subStr(_vendPurchOrderJour.PurchOrderDocNum,strLen(_vendPurchOrderJour.PurchOrderDocNum),-1);
                
                if(metDocVersion == '1')
                {
                    ret = true;
                }
                
                break;
        }
        
        return ret;
    }
